<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();require __DIR__.'/../../app/helpers/layout.php';render_start('Monitoring','Aktivitas dan audit trail',$u);dashboard_nav('admin');render_mid('Monitoring','Aktivitas sistem terbaru',$u);$rows=$pdo->query('SELECT a.*,COALESCE(u.name,"Sistem") user_display FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200')->fetchAll();?><div class="card"><div class="toolbar"><div><b>Activity Log</b><p class="muted">Login, pendaftaran, transaksi, dan perubahan data.</p></div><span class="badge red">LIVE</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>User</th><th>Role</th><th>Aksi</th><th>Deskripsi</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_display'])?></td><td><span class="badge"><?=e($r['role_name'])?></span></td><td><?=e($r['action'])?></td><td><?=e($r['description'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php render_end(); ?>
